contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function taking a destination address to pass to migrateTo
    function run(address to) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // No precondition on 'to'
        // Record observable before-values
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        bool reverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule:
        // - If call reverted, we make no claim about balances.
        // - If call succeeded, contract's balance must become zero afterwards, and this contract's observable balance cannot increase by more than the previous contract balance (no Ether creation).
        assert(
            reverted || (
                address(c).balance == 0
                && address(this).balance <= beforeThisBalance + beforeContractBalance
            )
        );
    }

    receive() external payable {}
}

